#define EG2_RM_BLOCK_COUNT 49
#define EG2_RM_REG_COUNT 3408
#define EG2_RM_MEM_COUNT 9
#define EG2_RM_INTR_COUNT 221
#define EG2_RM_REASON_COUNT 52
