#define EG2_RM_PLIC_PRIO_0 0x0
#define EG2_RM_PLIC_IP_0 0x1000
#define EG2_RM_PLIC_IE0_0 0x2000
#define EG2_RM_PLIC_THRESHOLD0 0x200000
#define EG2_RM_PLIC_CC0 0x200004

enum {
  kEg2RmShadowed = 0x01,  // two equal writes update it
  kEg2RmNoRead = 0x02,    // never read (why_r)
  kEg2RmNoWrite = 0x04,   // never written (why_w)
  kEg2RmNoReset = 0x08,   // no reset check (why_r)
  kEg2RmGapW = 0x10,      // the model does not model its write behaviour (why_w)
  kEg2RmGapR = 0x20,      // the model does not model its reset value (why_r)
  kEg2RmLockable = 0x40,  // a REGWEN the lock phase may lock
  kEg2RmWenMubi = 0x80,   // its REGWEN is a MuBi4 (open = 0x6), else one bit (open = 1)
};

enum {
  kEg2RmMemWritable = 1,
  kEg2RmMemByteWrite = 2,  // sub-word writes allowed
  kEg2RmMemTagged = 4,     // CHERIoT tags kept (main and sec SRAM)
  kEg2RmMemNextMapped = 8, // the address after the last is another window's
};

typedef struct eg2_rm_masks {
  uint32_t known;    // bits whose value the table predicts
  uint32_t rw;       // read back as written
  uint32_t w1c;      // a 1 clears
  uint32_t w1s;      // a 1 sets
  uint32_t rw0c;     // a 0 clears
  uint32_t rdzero;   // read as zero (wo, r0w1c)
  uint32_t mubi;     // multi-bit booleans: written True or False only
  uint32_t mtrue;    // their True encoding
  uint32_t neutral0; // rw1c, r0w1c, rw1s bits (predicted or not) a neutral write leaves 0
} eg2_rm_masks_t;

typedef struct eg2_rm_reg {
  uint32_t offset;
  uint32_t resval;   // what a read returns after reset, in the known bits
  uint32_t name;     // offset into kEg2RmNames
  uint16_t masks;    // index into kEg2RmMasks
  uint16_t regwen;   // index into kEg2RmRegs of the gating REGWEN, 0xffff none
  uint8_t flags;
  uint8_t permit;    // bytes holding fields: a write must enable all of them
  uint8_t why_w;     // reason (eg2_rm_reason) for kEg2RmNoWrite / kEg2RmGapW
  uint8_t why_r;     // reason for kEg2RmNoRead / kEg2RmNoReset / kEg2RmGapR
} eg2_rm_reg_t;

typedef struct eg2_rm_block {
  uint32_t base;
  uint32_t name;      // offset into kEg2RmNames
  uint16_t first;     // first register in kEg2RmRegs
  uint16_t count;
  uint16_t intr_state, intr_enable, intr_test;  // offsets, 0xffff none
  uint16_t intr0;     // first interrupt in kEg2RmIntrs
  uint8_t nintr;
  uint8_t alert0;     // first alert (alert-handler ID), 0xff none
  uint8_t nalert;
  uint8_t sw_rst;     // rstmgr SW_RST_CTRL_N index of its reset, 0xff none
  uint16_t probe_rd;  // register the connectivity test reads, 0xffff none
  uint16_t probe_wr;  // register it writes, 0xffff none
  uint32_t alert_test;  // ALERT_TEST offset, 0xffffffff none
} eg2_rm_block_t;

typedef struct eg2_rm_intr {
  uint8_t block;
  uint8_t bit;        // in INTR_STATE / INTR_ENABLE / INTR_TEST
  uint8_t status;     // status-type interrupt
  uint8_t pad;
  uint16_t plic_id;
} eg2_rm_intr_t;

typedef struct eg2_rm_mem {
  uint32_t base;
  uint32_t size;
  uint32_t name;      // offset into kEg2RmNames
  uint32_t flags;
} eg2_rm_mem_t;

