/** The reason an exclusion or model gap was recorded, from its ID. */
static inline const char *eg2_rm_reason(uint32_t id) {
  switch (id) {
    case 1:
      return "hjson CSR-test tag CsrExclAll: a write has a side effect";
    case 2:
      return "raises interrupts or alerts (eg2_connectivity raises them)";
    case 3:
      return "UART0 is the console";
    case 4:
      return "written by the console set-up (eg2_console_init, test ROM)";
    case 5:
      return "the read has a side effect (pops a FIFO or clears)";
    case 6:
      return "hwext: a write acts on the hardware directly";
    case 7:
      return "hjson CSR-test tag CsrExclWrite: a write has a side effect";
    case 8:
      return "write-only: a write is a command";
    case 9:
      return "no field software writes and hardware keeps";
    case 10:
      return "hjson CSR-test tag CsrExclWriteCheck: hardware changes the value";
    case 11:
      return "drives the I2C pads or enables the host or target";
    case 12:
      return "a REGWEN (rw0c): a 0 locks it until reset; the lock phase writes it, last";
    case 13:
      return "OTP background checks: a period or timeout too short for a check is a fatal error";
    case 14:
      return "locks software reads of an OTP partition";
    case 15:
      return "the life-cycle transition interface";
    case 16:
      return "the status module (eg2_status) owns the alert handler: enables, classes, escalation";
    case 17:
      return "enables the SPI host and its pads, or resets it";
    case 18:
      return "connects to the USB bus or drives its pads";
    case 19:
      return "low-power entry, wake-up and reset enables";
    case 20:
      return "resets the chip or a peripheral";
    case 21:
      return "the reset reason: hardware sets it at power-on";
    case 22:
      return "switches the clock source or its jitter";
    case 23:
      return "gates the clocks of blocks in use (UART0 among them)";
    case 24:
      return "clock measurement: thresholds that do not fit the clock are recoverable errors";
    case 25:
      return "drives the EC reset, key and power pins, or arms a combo action (a chip reset)";
    case 26:
      return "adc_ctrl's sample counts: its documentation says the value must be 1 or larger";
    case 27:
      return "pad routing and attributes: UART0's pads and the bench's straps";
    case 28:
      return "the test ROM routes the strap GPIOs, UART0 and UART1 (pinmux_testutils_init)";
    case 29:
      return "wake-up detectors: wake-up requests to the power manager";
    case 30:
      return "the watchdog: bark is an interrupt and NMI, bite a reset";
    case 31:
      return "the test ROM copies the AST configuration from OTP (CREATOR_SW_CFG_AST_CFG)";
    case 32:
      return "triggers AST alert events, makes them fatal, or sets pad attributes";
    case 33:
      return "renews the SRAM's key or wipes it";
    case 34:
      return "the test runs from RRAM: disable, execute, memory protection, operations";
    case 35:
      return "the test ROM enables RRAM execution and reads (nvm_testutils_rom_init)";
    case 36:
      return "the RRAM macro's configuration: the test runs from RRAM";
    case 37:
      return "the debug module's hart flags: a write signals the debug module";
    case 38:
      return "enables debug";
    case 39:
      return "hjson CSR-test tag: reset value not checked";
    case 40:
      return "KMAC's entropy settings: a wait-timer expiry is a KMAC error";
    case 41:
      return "starts a key manager operation";
    case 42:
      return "enables the entropy complex, which other blocks use";
    case 43:
      return "the test ROM enables CSRNG and EDN0 (test_rom_start.S)";
    case 44:
      return "enables or reconfigures the entropy source, which other blocks use";
    case 45:
      return "raises rv_core_ibex's software alerts";
    case 46:
      return "address translation: remaps the core's own fetches or loads";
    case 47:
      return "enables the NMI (rw1s, cannot be undone)";
    case 48:
      return "the execution-mode switch and its lock";
    case 49:
      return "the CHERIoT start-up code switches the mode";
    case 50:
      return "starts a revocation sweep";
    case 51:
      return "the CHERIoT start-up code renews the key and initialises the meta SRAM";
    default:
      return "";
  }
}
